}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String[] daftar = {"harga.txt", "hilang.txt", "promo.txt"};
        try (PrintWriter w = new PrintWriter(new FileWriter("harga.txt"))) {
            w.println("Kopi 15000");
        }
        try (PrintWriter w = new PrintWriter(new FileWriter("promo.txt"))) {
            w.println("Diskon 10%");
        }
        int hilang = 0;
        for (String nama : daftar) {
            try (BufferedReader r = new BufferedReader(new FileReader(nama))) {
                System.out.println(nama + ": " + r.readLine());
            } catch (FileNotFoundException e) {
                System.out.println(nama + ": belum ada");
                hilang++;
            }
        }
        System.out.println("File hilang: " + hilang);
    }
}

