import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        try (PrintWriter w = new PrintWriter(new FileWriter("ada.txt"))) {
            w.println("Halo dari ada.txt");
        }
        String nama = new Scanner(System.in).nextLine();
        try (BufferedReader r = new BufferedReader(new FileReader(nama))) {
            System.out.println(r.readLine());
        } catch (FileNotFoundException e) {
            System.out.println("File " + nama + " tidak ditemukan");
        }
    }
}
